import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/GPT1%E8%AB%96%E6%96%87.html","title":"GPT1論文","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.52,"words":157},"filePathRelative":"GPT1論文.md"}`),a={name:`GPT1論文.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="gpt1論文" tabindex="-1"><a class="header-anchor" href="#gpt1論文"><span>GPT1論文</span></a></h1><p>GPT1の<a href="./論文.html">論文</a>、Improving Language Understanding by Generative Pre-Trainingの事。</p><ul><li><a href="https://cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf" target="_blank" rel="noopener noreferrer">Improving Language Understanding by Generative Pre-Training</a> pdf</li><li><a href="https://openai.com/index/language-unsupervised/" target="_blank" rel="noopener noreferrer">Improving language understanding with unsupervised learning - OpenAI</a> ブログ記事</li></ul><h2 id="概要" tabindex="-1"><a class="header-anchor" href="#概要"><span>概要</span></a></h2><p><a href="./Transformer.html">Transformer</a>のデコーダーのみでlanguage modelを学習しまくって、それをtransfer learningするといろんなタスクで良いよ、という論文。 ラベル無しの文章で学習してスコアをあげるという試み。</p><p>タスクごとにモデルを作るのでは無く、全てのタスクをk個のトークンを元に次のトークンを予測する、という枠組みに変形する事で同じモデルを使うというのがアイデアではある。</p><p>ただし問題に合わせたfine tuneはする。4択とかはそれぞれの単語の確率のsoftmaxにしたりとか結構問題ごとに手は入れる。 最後のレイヤーだけでどうにかする、という感じ。</p><h2 id="モデルとパラメータ数" tabindex="-1"><a class="header-anchor" href="#モデルとパラメータ数"><span>モデルとパラメータ数</span></a></h2><p><a href="./Transformerブロック.html">Transformerブロック</a>が一つで2Mi個くらいなのに、GPT1は<a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の表4.1によると117M個らしい。 レイヤー数と合わない気がするのでもう少し詳しく見ていく。</p><p>モデルは12レイヤーのデコーダーオンリーモデルで、dは768次元、ヘッドは12個、FFNは間を3072にしている、との事。</p><p>計算してみる。</p><p><img src="/RandomThoughts/assets/0000-Bv_th-Kg.png" alt="imgs/GPT1/0000.png"></p><p>結構違うのだが。embedの行列か？</p><p>embedの行列も計算して足してみる。 vocabは40000。</p><p><img src="/RandomThoughts/assets/0001-DoZN_8ca.png" alt="imgs/GPT1/0001.png"></p><p>という事で117M個くらいになりそうで無事一致。っていうかembedって大きいんだなぁ。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};